"""
Phase 3.2 — Human annotation harness (label sheets + Cohen's kappa).

The wrong-query corpus is generated by literature-motivated operators, but its
misconception labels only gain construct validity when independent humans,
shown the (question, gold, wrong) triple WITHOUT the operator name, assign the
same misconception. This module:

  1. `make-sheet`  : draws a stratified, seeded, SHUFFLED sample from the
     corpus and writes
        - a blind label sheet (CSV) for each annotator — no operator column,
          no expected label, no detector output;
        - a sealed answer key (separate CSV) mapping row ids to the intended
          label and the detector's output.
  2. `kappa`       : computes Cohen's kappa between two annotator CSVs, and
     each annotator's agreement with the intended labels and with the
     detector.

Annotators pick labels from the closed vocabulary below (multi-label allowed,
';'-separated, first = primary) or NONE / OTHER — so disagreement with the
intended label is expressible, which is what makes the exercise meaningful.

Usage:
    python external/spider/annotation.py make-sheet --n 120 --annotators 2
    python external/spider/annotation.py kappa --a labels_A.csv --b labels_B.csv
"""
import os
import csv
import sys
import json
import random
import argparse
from collections import defaultdict, Counter
from typing import List, Dict, Optional

_EXTERNAL_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
_REPO_ROOT = os.path.dirname(_EXTERNAL_DIR)
if _REPO_ROOT not in sys.path:
    sys.path.insert(0, _REPO_ROOT)

_DERIVED_DIR = os.path.join(_EXTERNAL_DIR, "data", "derived")
_ANNOT_DIR = os.path.join(_DERIVED_DIR, "annotation")

LABEL_VOCAB = [
    "MISSING_WHERE", "WRONG_JOIN_TYPE", "CARTESIAN_PRODUCT", "MISSING_GROUP_BY",
    "HAVING_vs_WHERE", "WRONG_SET_OP", "IN_FOR_DIVISION", "NOT_IN_vs_NOT_EXISTS",
    "MISSING_CORRELATED_REF", "IN_vs_EXISTS", "NULL_EQUALITY", "NONE", "OTHER",
]

SEED = 20260709   # fixed for reproducibility; report it in the paper


def _load_corpus(split: str = "dev") -> List[Dict]:
    path = os.path.join(_DERIVED_DIR, f"spider_wrong_{split}.json")
    if not os.path.exists(path):
        raise FileNotFoundError(
            f"{path} not found - run gen_wrong.py first.")
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def make_sheet(split: str = "dev", n: int = 120, annotators: int = 2) -> None:
    corpus = _load_corpus(split)
    # Only rows that were actually applied (diverging) enter the sample:
    # latent skips never reach a student, so their label is untestable.
    pool = [e for e in corpus if e.get("outcome") in ("HIT", "MISS")]
    by_op: Dict[str, List[Dict]] = defaultdict(list)
    for e in pool:
        by_op[e["operator"]].append(e)

    rng = random.Random(SEED)
    ops = sorted(by_op)
    per_op = max(1, n // len(ops))
    sample: List[Dict] = []
    for op in ops:
        rows = by_op[op][:]
        rng.shuffle(rows)
        sample.extend(rows[:per_op])
    rng.shuffle(sample)                      # blind the operator blocking

    os.makedirs(_ANNOT_DIR, exist_ok=True)
    key_path = os.path.join(_ANNOT_DIR, f"answer_key_{split}.csv")
    with open(key_path, "w", newline="", encoding="utf-8") as fh:
        w = csv.writer(fh)
        w.writerow(["item_id", "operator", "intended_label",
                    "detector_labels", "db_id"])
        for i, e in enumerate(sample):
            w.writerow([f"Q{i+1:03d}", e["operator"], e["expected"],
                        ";".join(e.get("detected_keys", [])), e["db_id"]])

    for a in range(1, annotators + 1):
        sheet_path = os.path.join(_ANNOT_DIR, f"label_sheet_{split}_annotator{a}.csv")
        with open(sheet_path, "w", newline="", encoding="utf-8") as fh:
            w = csv.writer(fh)
            w.writerow(["item_id", "db_id", "question", "gold_sql", "wrong_sql",
                        "label", "notes"])
            for i, e in enumerate(sample):
                w.writerow([f"Q{i+1:03d}", e["db_id"], e["question"],
                            e["gold_sql"], e["wrong_sql"], "", ""])
        print(f"wrote blind sheet : {sheet_path}")
    print(f"wrote sealed key  : {key_path}   (do NOT open before labeling)")
    print(f"sample: {len(sample)} items, {per_op} per operator, seed={SEED}")
    print("\nLabel vocabulary (put PRIMARY label first; ';' separates multi-labels):")
    for lab in LABEL_VOCAB:
        print(f"  {lab}")


def _read_labels(path: str) -> Dict[str, str]:
    out = {}
    with open(path, "r", encoding="utf-8-sig", newline="") as fh:
        for row in csv.DictReader(fh):
            primary = (row.get("label") or "").split(";")[0].strip().upper()
            out[row["item_id"].strip()] = primary
    return out


def cohens_kappa(a: Dict[str, str], b: Dict[str, str]) -> Optional[float]:
    items = sorted(set(a) & set(b))
    items = [i for i in items if a[i] and b[i]]
    n = len(items)
    if n == 0:
        return None
    po = sum(1 for i in items if a[i] == b[i]) / n
    ca, cb = Counter(a[i] for i in items), Counter(b[i] for i in items)
    pe = sum(ca[k] * cb.get(k, 0) for k in ca) / (n * n)
    if pe == 1.0:
        return 1.0
    return (po - pe) / (1 - pe)


def kappa_report(path_a: str, path_b: str, split: str = "dev") -> None:
    a, b = _read_labels(path_a), _read_labels(path_b)
    k_ab = cohens_kappa(a, b)
    n = len([i for i in set(a) & set(b) if a[i] and b[i]])
    print(f"items labeled by both : {n}")
    print(f"Cohen's kappa (A vs B): {k_ab if k_ab is None else round(k_ab, 3)}")

    key_path = os.path.join(_ANNOT_DIR, f"answer_key_{split}.csv")
    if os.path.exists(key_path):
        intended, detector = {}, {}
        with open(key_path, "r", encoding="utf-8-sig", newline="") as fh:
            for row in csv.DictReader(fh):
                intended[row["item_id"]] = row["intended_label"].upper()
                detector[row["item_id"]] = (row["detector_labels"] or "").split(";")[0].upper()
        for name, ann in (("A", a), ("B", b)):
            k_int = cohens_kappa(ann, intended)
            k_det = cohens_kappa(ann, detector)
            print(f"annotator {name} vs intended : "
                  f"{k_int if k_int is None else round(k_int, 3)}")
            print(f"annotator {name} vs detector : "
                  f"{k_det if k_det is None else round(k_det, 3)}")


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description="Annotation sheets and Cohen's kappa")
    sub = ap.add_subparsers(dest="cmd", required=True)
    ms = sub.add_parser("make-sheet")
    ms.add_argument("--split", default="dev")
    ms.add_argument("--n", type=int, default=120)
    ms.add_argument("--annotators", type=int, default=2)
    kp = sub.add_parser("kappa")
    kp.add_argument("--a", required=True)
    kp.add_argument("--b", required=True)
    kp.add_argument("--split", default="dev")
    args = ap.parse_args()
    if args.cmd == "make-sheet":
        make_sheet(split=args.split, n=args.n, annotators=args.annotators)
    else:
        kappa_report(args.a, args.b, split=args.split)
